void GF_SndStartFadeInBGM(int targetVolume, int frames, enum BGMFadeInType fadeInType);
void GF_SndStartFadeOutBGM(int targetVolume, int frames);
BOOL GF_SndGetFadeTimer(void);

void GF_SndStartFadeInBGM(int targetVolume, int frames, enum BGMFadeInType fadeInType) {
    u16 currentBGM = Sound_GetCurrentBGM();
    u8 playerID = GF_GetPlayerNoBySeq(currentBGM);
    if (playerID == 0xFF) {
        return;
    }

    enum SoundHandleType handleType = GF_GetSndHandleByPlayerNo(playerID);

    if (fadeInType == BGM_FADE_IN_TYPE_FROM_ZERO) {
        GF_SndHandleMoveVolume(handleType, 0, 0);
    }

    GF_SndHandleMoveVolume(handleType, targetVolume, frames);
    sub_02005990(frames);
    GF_SndSetState(SOUND_SYSTEM_STATE_FADE_IN);
}

void GF_SndStartFadeOutBGM(int targetVolume, int frames) {
    u16 currentBGM = Sound_GetCurrentBGM();
    u8 playerID = GF_GetPlayerNoBySeq(currentBGM);
    if (playerID == 0xFF) {
        return;
    }

    if (GF_SndGetFadeTimer() == 0) {
        enum SoundHandleType handleType = GF_GetSndHandleByPlayerNo(playerID);
        GF_SndHandleMoveVolume(handleType, targetVolume, frames);
        sub_02005990(frames);
    }

    GF_SndSetState(SOUND_SYSTEM_STATE_FADE_OUT);
}

BOOL GF_SndGetFadeTimer(void) {
    u16 *param = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_FADE_COUNTER);
    return *param;
}
